    result[str(mult)]={'variables':list(map(str,vs)),'equations':list(map(str,eq)),'groebner':list(map(str,gb))}
pathlib.Path('workspace/agent4_n3_width2_checks.py').write_text(pathlib.Path(__file__).read_text())
